catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) return;

    var department = g_form.getValue('department');
    var quarter = g_form.getValue('reward_quarter');

    if (!department || !quarter) {
        g_form.setValue('remaining_budget_display', '');
        return;
    }

    // Look up the department reward budget for the given department, quarter, and current year
    var ga = new GlideAjax('x_1939412_employ_0.RewardBudgetLookup');
    ga.addParam('sysparm_name', 'getRemainingBudget');
    ga.addParam('sysparm_department', department);
    ga.addParam('sysparm_quarter', quarter);
    ga.getXMLAnswer(function (answer) {
        if (answer && answer !== 'null') {
            g_form.setValue('remaining_budget_display', answer);
        } else {
            g_form.setValue('remaining_budget_display', 'No budget found');
        }
    });
}
